const $=id=>document.getElementById(id),fmt=n=>new Intl.NumberFormat('en-US',{maximumFractionDigits:1}).format(Number(n||0)),date=s=>s?new Intl.DateTimeFormat('en-US',{dateStyle:'medium'}).format(new Date(s)):'—';
const COLORS=['#2f6fdd','#6f55d9','#e18732','#159aa5','#2a9b63','#c95d7b','#6a7b91','#b59028'];let appliedStart='',appliedEnd='',availablePrograms=[];
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function notice(text,ok=true){$('notice').innerHTML=text?`<div class="notice ${ok?'ok':'bad'}">${esc(text)}</div>`:''}function bar(v){return `<div class="bar"><i style="width:${Math.min(100,Math.max(0,Number(v)||0))}%"></i></div>`}function initials(name){return String(name||'V').trim().split(/\s+/).slice(0,2).map(x=>(x[0]||'').toUpperCase()).join('')||'V'}function query(){const q=new URLSearchParams();if(appliedStart)q.set('start',appliedStart);if(appliedEnd)q.set('end',appliedEnd);return q.size?'?'+q.toString():''}function rangeText(){return appliedStart||appliedEnd?`${appliedStart||'Beginning'} through ${appliedEnd||'Present'}`:'All synchronized dates'}
function renderVisuals(p){const totalHours=p.reduce((a,x)=>a+Number(x.knownHours||0),0),totalCredits=p.reduce((a,x)=>a+Number(x.volunteerCredits||0),0);$('volEq').textContent=fmt(totalCredits);let cursor=0,parts=[];p.forEach((x,i)=>{const pct=totalCredits?Number(x.volunteerCredits||0)/totalCredits*100:0,start=cursor;cursor+=pct;parts.push(`${COLORS[i%COLORS.length]} ${start}% ${cursor}%`)});$('donut').style.background=parts.length?`conic-gradient(${parts.join(',')})`:'#e8edf5';$('mixLegend').innerHTML=p.length?p.map((x,i)=>{const pct=totalCredits?Number(x.volunteerCredits||0)/totalCredits*100:0;return `<div class="legendRow"><i style="background:${COLORS[i%COLORS.length]}"></i><span>${esc(x.name)}</span><b>${fmt(x.volunteerCredits)}</b><em>${Math.round(pct)}%</em></div>`}).join(''):'<div class="empty">No volunteer mix data.</div>';const max=Number(p[0]?.knownHours||1);$('ranking').innerHTML=p.length?p.map((x,i)=>`<div class="rankRow"><span class="rankNo ${i<3?'top'+(i+1):''}">${i+1}</span><div><div class="rankLabel"><strong>${esc(x.name)}</strong><b>${fmt(x.knownHours)} hrs</b></div>${bar(Number(x.knownHours||0)/max*100)}<small>${totalHours?Math.round(Number(x.knownHours||0)/totalHours*100):0}% of all credited hours</small></div></div>`).join(''):'<div class="empty">No program performance data.</div>'}
async function saveOverride(email,name,programs,button){button.disabled=true;button.textContent='Saving…';try{const r=await fetch('/api/attribution/override',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({email,name,programs})});const d=await r.json();if(!r.ok)throw Error(d.error);notice(d.message,true);await load()}catch(e){notice(e.message||'Unable to save manual program assignment',false)}finally{button.disabled=false;button.textContent='Save Assignment'}}
function bindReviewEditors(){document.querySelectorAll('[data-assign-email]').forEach(btn=>btn.addEventListener('click',()=>{const email=btn.getAttribute('data-assign-email'),editor=document.querySelector(`[data-editor="${CSS.escape(email)}"]`);document.querySelectorAll('.assignmentEditor').forEach(x=>{if(x!==editor)x.hidden=true});editor.hidden=!editor.hidden}));document.querySelectorAll('[data-save-email]').forEach(btn=>btn.addEventListener('click',()=>{const email=btn.getAttribute('data-save-email'),name=btn.getAttribute('data-name')||'',editor=document.querySelector(`[data-editor="${CSS.escape(email)}"]`),programs=[...editor.querySelectorAll('input[type=checkbox]:checked')].map(x=>x.value);if(!programs.length){notice('Select at least one program before saving.',false);return}saveOverride(email,name,programs,btn)}))}
async function load(){try{const r=await fetch('/api/dashboard'+query()),d=await r.json();if(!r.ok)throw Error(d.error);const s=d.summary||{},cfg=d.settings||{};availablePrograms=d.availablePrograms||[];$('rangeStatus').textContent=rangeText();$('needed').textContent=fmt(s.hoursNeeded);$('filled').textContent=fmt(s.hoursFilled);$('remaining').textContent=fmt(s.hoursRemaining);$('events').textContent=fmt(s.activeEvents);$('rate').textContent=`${Math.round(s.fillRate||0)}% of known/estimated demand`;$('open').textContent=`${s.openSlots||0} open volunteer positions`;$('assigned').textContent=`${s.assignedSlots||0} filled · ${s.totalAssignments||0} total positions`;$('last').textContent=date(s.lastSyncAt);$('contactLast').textContent=date(s.contactSyncAt);$('rosterMappings').textContent=fmt(s.contactMappings);$('manualOverrides').textContent=fmt(s.manualOverrideEmails);$('ambiguousCount').textContent=fmt(s.ambiguousVolunteers);$('unmatchedCount').textContent=fmt(s.unmatchedVolunteers);const mp=s.volunteerEmails?Math.round((s.matchedVolunteers||0)/s.volunteerEmails*100):0;$('matchPct').textContent=`${mp}%`;$('matchNote').textContent=`${s.matchedVolunteers||0} attributed · ${s.unmatchedVolunteers||0} unmatched`;$('estimateEnabled').checked=!!cfg.estimateUntimedEnabled;$('estimateHours').value=Number(cfg.estimateUntimedHours??6);$('estimateHours').disabled=!cfg.estimateUntimedEnabled;$('neededLabel').textContent=cfg.estimateUntimedEnabled?'Hours Needed (incl. estimates)':'Known Hours Needed';$('neededNote').textContent=cfg.estimateUntimedEnabled?`${fmt(s.estimatedHoursNeeded)} estimated`:`${s.tbdAssignments||0} assignments still TBD`;
const p=d.programs||[],total=p.reduce((a,x)=>a+Number(x.knownHours||0),0);renderVisuals(p);$('programList').className='';$('programList').innerHTML=p.length?p.map(x=>{const pct=total?Number(x.knownHours||0)/total*100:0;return `<div class="program"><div><strong>${esc(x.name)}</strong><small>${fmt(x.volunteerCredits)} volunteer equivalents · ${fmt(x.tbdAssignments)} TBD assignment credit</small></div><b>${fmt(x.knownHours)} hrs</b><span>${Math.round(pct)}%</span>${bar(pct)}</div>`}).join(''):'<div class="empty">No program-attributed activity in this date range.</div>';
const e=d.events||[];$('eventList').innerHTML=e.length?e.map(x=>`<div class="event"><strong>${esc(x.title)}</strong><small>${date(x.eventDate)} · ${esc(x.location||'Location not set')}</small><div class="nums"><span>${fmt(x.hoursFilled)} filled hrs</span><span>${fmt(x.hoursNeeded)} needed hrs</span><span>${x.openSlots||0} open</span>${x.tbdQty>0?`<span>${x.tbdQty} TBD</span>`:''}</div>${bar(x.hoursNeeded?x.hoursFilled/x.hoursNeeded*100:0)}</div>`).join(''):'<div class="empty">No synchronized assignments fall in this date range.</div>';
const v=d.volunteers||[];$('volunteerList').className='';$('volunteerList').innerHTML=v.length?v.slice(0,80).map(x=>{const names=x.attribution==='Unmatched'?[]:String(x.attribution||'').split(',').map(a=>a.trim()).filter(Boolean),share=names.length?Number(x.knownHours||0)/names.length:0,badges=names.length?names.map(n=>`<span class="badge matched">${esc(n)}</span>`).join(''):'<span class="badge unmatched">Unmatched</span>',alloc=names.length?names.map(n=>`<small>${esc(n)}: <b>${fmt(share)}h</b> (${Math.round(100/names.length)}%)</small>`).join(''):'<small>—</small>';return `<div class="volrow"><div class="volIdentity"><span class="avatar">${esc(initials(x.name))}</span><div><strong>${esc(x.name)}</strong>${x.email?`<small>${esc(x.email)}${x.manualOverride?' · manual':''}</small>`:''}</div></div><div class="badgeWrap">${badges}</div><b class="hoursValue">${fmt(x.knownHours)}</b><div class="allocation">${alloc}</div><span>${fmt(x.assignments)}</span><span>${fmt(x.tbdAssignments)}</span></div>`}).join(''):'<div class="empty">No filled volunteer records in this date range.</div>';
const u=d.unmatched||[];$('reviewList').className='';$('reviewList').innerHTML=u.length?`<div class="reviewList">${u.slice(0,80).map((x,i)=>{const email=x.email||'',checks=availablePrograms.map(program=>`<label><input type="checkbox" value="${esc(program)}"><span>${esc(program)}</span></label>`).join('');return `<div class="reviewItem"><div class="reviewSummary"><div class="volIdentity"><span class="avatar warningAvatar">${esc(initials(x.name))}</span><div><strong>${esc(x.name)}</strong><small>${esc(email||'No email available')}</small></div></div><span><b>${fmt(x.knownHours)}</b> known hrs</span><span>${fmt(x.tbdAssignments)} TBD</span><button class="secondary smallBtn" ${email?'':'disabled'} data-assign-email="${esc(email)}">Assign Program</button></div>${email?`<div class="assignmentEditor" data-editor="${esc(email)}" hidden><strong>Select every program this volunteer represents</strong><div class="programChecks">${checks}</div><div class="editorActions"><small>Multiple selections split hours evenly.</small><button data-save-email="${esc(email)}" data-name="${esc(x.name)}">Save Assignment</button></div></div>`:''}</div>`}).join('')}</div>`:'<div class="empty successEmpty">✓ Every volunteer in this date range has a program attribution.</div>';bindReviewEditors()}catch(e){notice(e.message||'Unable to load dashboard',false)}}
$('applyRange').onclick=async()=>{const a=$('startDate').value,b=$('endDate').value;if(a&&b&&a>b){notice('Start date cannot be after end date.',false);return}appliedStart=a;appliedEnd=b;notice('');await load()};$('clearRange').onclick=async()=>{$('startDate').value='';$('endDate').value='';appliedStart='';appliedEnd='';notice('');await load()};$('estimateEnabled').onchange=()=>{$('estimateHours').disabled=!$('estimateEnabled').checked};$('saveSettings').onclick=async()=>{const b=$('saveSettings');b.disabled=true;b.textContent='Saving…';notice('');try{const payload={estimateUntimedEnabled:$('estimateEnabled').checked,estimateUntimedHours:Number($('estimateHours').value)},r=await fetch('/api/settings',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)}),d=await r.json();if(!r.ok)throw Error(d.error);notice('Settings saved.',true);await load()}catch(e){notice(e.message||'Unable to save settings',false)}finally{b.disabled=false;b.textContent='Save'}};$('syncContacts').onclick=async()=>{const b=$('syncContacts');b.disabled=true;b.textContent='Syncing contacts…';notice('');try{const r=await fetch('/api/contacts/sync',{method:'POST'}),d=await r.json();if(!r.ok)throw Error(d.error);notice(d.message,true);await load()}catch(e){notice(e.message||'Contact sync failed',false)}finally{b.disabled=false;b.textContent='Sync Contacts'}};$('sync').onclick=async()=>{const b=$('sync');b.disabled=true;b.textContent='Syncing…';notice('');try{const r=await fetch('/api/sync',{method:'POST'}),d=await r.json();if(!r.ok)throw Error(d.error);notice(d.message,true);await load()}catch(e){notice(e.message||'Sync failed',false)}finally{b.disabled=false;b.textContent='Sync All'}};load();
